import React, { useState } from "react";

const ToDoList = () => {
  const [tasks, setTasks] = useState([]);
  const [task, setTask] = useState("");
  const [editIndex, setEditIndex] = useState(null);

  // Task add/update function
  const addTask = () => {
    if (task.trim() === "") return;
    if (editIndex !== null) {
      const updatedTasks = [...tasks];
      updatedTasks[editIndex] = task;
      setTasks(updatedTasks);
      setEditIndex(null);
    } else {
      setTasks([...tasks, task]);
    }
    setTask("");
  };

  // Task delete function
  const deleteTask = (index) => {
    const filteredTasks = tasks.filter((_, i) => i !== index);
    setTasks(filteredTasks);
  };

  // Task edit function
  const editTask = (index) => {
    setTask(tasks[index]);
    setEditIndex(index);
  };

  return (
    <div className="max-w-md mx-auto p-4 bg-white shadow-lg rounded-lg">
      <h2 className="text-2xl font-bold text-center mb-4">To-Do List</h2>

      <div className="flex">
        <input
          type="text"
          value={task}
          onChange={(e) => setTask(e.target.value)}
          placeholder="Enter a task..."
          className="w-full p-2 border rounded-l"
        />
        <button onClick={addTask} className="bg-blue-500 text-white px-4 py-2 rounded-r">
          {editIndex !== null ? "Update" : "Add"}
        </button>
      </div>

      <ul className="mt-4">
        {tasks.map((t, index) => (
          <li key={index} className="flex justify-between items-center bg-gray-100 p-2 mt-2 rounded">
            <span>{t}</span>
            <div>
              <button onClick={() => editTask(index)} className="bg-yellow-400 text-white px-2 py-1 mr-2 rounded">
                Edit
              </button>
              <button onClick={() => deleteTask(index)} className="bg-red-500 text-white px-2 py-1 rounded">
                Delete
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ToDoList;
